use super::*;

/// Does `body` reference any of `targets` as a whole-word identifier, other than `own` (its own name,
/// which appears in its signature)? Splits on non-ident chars, so `add` inside `address` does not match.
pub(crate) fn body_references_private(body: &str, own: &str, targets: &std::collections::HashSet<String>) -> bool {
    if targets.is_empty() {
        return false;
    }
    body.split(|c: char| !c.is_alphanumeric() && c != '_').any(|tok| tok != own && targets.contains(tok))
}
